function attachSignin() {
  const { google } = window as any;

  if (google) {
    // 将当前页面 URL（仅 query 部分，去除 hash）作为 redirect 参数传给服务端, 如果不存在，则传一个默认值,这样不用处理用?还是&
    const queryStr = window.location.search.split("?")[1] || "axx=1";
    const query = Qs.parse(queryStr);
    const loginUri = `${GOOGLE_REDIRECT_CALLBACK_URL}`;

    // 不要把 hash 也带上，因为打开的 url， hash 值有点怪
    const urlWithQuery = `${window.location.origin}${window.location.pathname}?${queryStr}`;
    google.accounts.id.initialize({
      client_id: CLIENT_ID,
      ux_mode: "redirect",
      login_uri: loginUri,
      state: JSON.stringify({
        ...query,
        redirect_to: urlWithQuery,
      }),
    });
    google.accounts.id.renderButton(document.getElementById("google-login-btn"), {
      theme: "outline",
      size: "large",
      type: "standard",
      width: "311",
      ux_mode: "redirect",
      login_uri: loginUri,
    });
  }
}

